1. Crea il file `res://shaders/outline.gdshader`.
2. Nello shader dichiara `shader_type canvas_item;` e i parametri uniform: `line_color` (`vec4` di tipo `source_color`, default giallo `vec4(1.0, 1.0, 0.0, 1.0)`) e `line_thickness` (`float` da 0.0 a 10.0, default `0.0`).
3. Nella funzione `fragment()`, controlla il colore del pixel. Se `color.a == 0.0` e `line_thickness > 0.0`, controlla l'alpha dei 4 pixel adiacenti a distanza `TEXTURE_PIXEL_SIZE * line_thickness`. Se almeno un vicino ha `alpha > 0.0`, imposta `COLOR = line_color;`. Negli altri casi assegna `COLOR = color;`.
4. Nella scena `res://objects/sign.tscn`, assegna allo `Sprite2D` un `ShaderMaterial` che usa `res://shaders/outline.gdshader`.
5. In `res://objects/sign.tscn`, aggiungi un nodo `Area2D` chiamato `InteractionArea` con una `CollisionShape2D` (forma rettangolare o circolare) per rilevare la vicinanza del giocatore.
6. Collega uno script `res://objects/sign.gd` al nodo radice `Sign`. Quando un corpo del gruppo `"player"` entra in `InteractionArea`, imposta `line_thickness` a `1.5`. Quando esce, imposta `line_thickness` a `0.0`.","modalita":"progetto","passiGuida":[],"suggerimenti":["Spostati di TEXTURE_PIXEL_SIZE * line_thickness per campionare i pixel vicini sopra, sotto, a destra e a sinistra.","Puoi usare max() per verificare se l'opacità massima dei 4 vicini è maggiore di 0.0.","Nello script sign.gd, controlla se body.is_in_group("player") nei metodi collegati a body_entered e body_exited prima di variare il parametro dello shader."],"verifiche":[{"tipo":"file_esiste","percorso":"res://shaders/outline.gdshader","descrizione":"Il file res://shaders/outline.gdshader è stato creato"},{"tipo":"file_esiste","percorso":"res://objects/sign.gd","descrizione":"Lo script res://objects/sign.gd è stato creato"},{"tipo":"nodo","scena":"res://objects/sign.tscn","tipoNodo":"Area2D","nome":"InteractionArea","descrizione":"La scena res://objects/sign.tscn ha un nodo Area2D chiamato InteractionArea"},{"tipo":"script_godot","descrizione":"Quando il giocatore si avvicina al cartello, il parametro line_thickness si attiva a 1.5 e torna a 0.0 quando si allontana","codice":"extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var sign_scene := instantiate_scene("res://objects/sign.tscn")
	if not check("sign_scene", sign_scene != null, "La scena res://objects/sign.tscn deve caricarsi senza errori"):
		return
	var area := find_by_name(sign_scene, "InteractionArea") as Area2D
	if not check("area", area != null, "Sign deve contenere un'Area2D chiamata InteractionArea"):
		return
	var sprite := find_by_name(sign_scene, "Sprite2D") as Sprite2D
	if not check("sprite", sprite != null and sprite.material is ShaderMaterial, "Lo Sprite2D di Sign deve avere uno ShaderMaterial"):
		return
	var mat := sprite.material as ShaderMaterial
	var dummy_player := CharacterBody2D.new()
	dummy_player.add_to_group("player")
	sign_scene.add_child(dummy_player)
	dummy_player.global_position = area.global_position
	await wait_physics_frames(4)
	var thick_in = float(mat.get_shader_parameter("line_thickness"))
	check("thick_entered", thick_in > 0.0, "Quando il giocatore entra in InteractionArea, line_thickness deve essere > 0.0 (trovato %s)" % str(thick_in))
	dummy_player.global_position = Vector2(9999, 9999)
	await wait_physics_frames(4)
	var thick_out = float(mat.get_shader_parameter("line_thickness"))
	check("thick_exited", thick_out == 0.0, "Quando il giocatore esce da InteractionArea, line_thickness deve tornare a 0.0 (trovato %s)" % str(thick_out))
"}],"soluzione":{"progetto":{"nome":"Salti","scenaPrincipale":"res://main.tscn"},"file":[{"percorso":"shaders/outline.gdshader","contenuto":"shader_type canvas_item;

uniform vec4 line_color : source_color = vec4(1.0, 1.0, 0.0, 1.0);
uniform float line_thickness : hint_range(0.0, 10.0) = 0.0;

void fragment() {
	vec4 color = texture(TEXTURE, UV);
	if (color.a == 0.0 && line_thickness > 0.0) {
		vec2 size = TEXTURE_PIXEL_SIZE * line_thickness;
		float alpha_up = texture(TEXTURE, UV + vec2(0.0, -size.y)).a;
		float alpha_down = texture(TEXTURE, UV + vec2(0.0, size.y)).a;
		float alpha_left = texture(TEXTURE, UV + vec2(-size.x, 0.0)).a;
		float alpha_right = texture(TEXTURE, UV + vec2(size.x, 0.0)).a;
		float max_neighbor = max(max(alpha_up, alpha_down), max(alpha_left, alpha_right));
		if (max_neighbor > 0.0) {
			COLOR = line_color;
		} else {
			COLOR = color;
		}
	} else {
		COLOR = color;
	}
}
